from typing import Callable, Dict, Tuple, Any, Hashable, TypeVar, Generic, Optional
from functools import wraps
import time
import collections

T = TypeVar('T')
K = TypeVar('K')

class TTLCache(Generic[K, T]):
    def __init__(self, maxsize: int, ttl: int, timer: Callable[[], float], typed: bool):
        self.cache: Dict[K, Tuple[T, float]] = collections.OrderedDict()
        self.maxsize = maxsize
        self.ttl = ttl
        self.timer = timer
        self.typed = typed

    def __getitem__(self, key: K) -> T:
        value, expire = self.cache[key]
        if expire < self.timer():
            del self.cache[key]
            raise KeyError(key)
        return value

    def __setitem__(self, key: K, value: T) -> None:
        if len(self.cache) >= self.maxsize:
            self.cache.popitem(last=False)
        expire = self.timer() + self.ttl
        self.cache[key] = (value, expire)

    def __delitem__(self, key: K) -> None:
        del self.cache[key]

    def __contains__(self, key: K) -> bool:
        try:
            self[key]
            return True
        except KeyError:
            return False

    def __len__(self) -> int:
        return len(self.cache)

    def has_key(self, key: K) -> bool:
        return key in self

def ttl_cache(maxsize: int = 128, ttl: int = 600, timer: Callable[[], float] = time.monotonic, typed: bool = False):
    def decorator(func: Callable[..., T]) -> Callable[..., T]:
        cache = TTLCache(maxsize, ttl, timer, typed)

        @wraps(func)
        def wrapper(*args: Any, **kwargs: Any) -> T:
            key = (func, args, tuple(kwargs.items())) if typed else (func, tuple(args), tuple(kwargs.items()))
            try:
                value = cache[key]
                value[1] = timer() + ttl  # Reset TTL
                return value[0]
            except KeyError:
                value = func(*args, **kwargs)
                cache[key] = (value, timer() + ttl)
                return value

        return wrapper

    return decorator
