def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.

    """
    def decorator(func):
        if maxsize is None:
            maxsize = 128
        if typed is None:
            typed = False
        return wraps(func)(lru_cache(maxsize=maxsize, typed=typed)(func))
    return decorator
