def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    # Assuming self.storage_root is the root of the hierarchy
    for obj in self._traverse_hierarchy(self.storage_root):
        num_objects += 1
        if self._is_valid_object(obj, validate_objects, check_digests):
            good_objects += 1

    if show_warnings and num_objects != good_objects:
        print(f"Warning: {num_objects - good_objects} objects were not valid.")

    return num_objects, good_objects

def _traverse_hierarchy(self, node):
    """Traverse the hierarchy starting from the given node."""
    yield node
    for child in node.children:
        yield from self._traverse_hierarchy(child)

def _is_valid_object(self, obj, validate_objects, check_digests):
    """Check if the object is valid based on the given flags."""
    if validate_objects and not obj.is_valid():
        return False
    if check_digests and not obj.check_digest():
        return False
    return True
