def deep_merge_nodes(nodes):
    merged_nodes = {}
    for key_node, value_node in nodes:
        if key_node.value not in merged_nodes:
            merged_nodes[key_node.value] = (key_node, value_node)
        else:
            existing_key_node, existing_value_node = merged_nodes[key_node.value]
            new_value_node = _merge_nodes(key_node, value_node, existing_value_node)
            merged_nodes[key_node.value] = (key_node, new_value_node)
