def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    seen = set()
    queue = [cls]

    while queue:
        c = queue.pop()
        if c not in seen:
            seen.add(c)
            queue.extend(c.__subclasses__())

    return seen

