def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    for command in commands:
        try:
            command_with_args = [command] + args
            if hide_stderr:
                with open(os.devnull, 'w') as devnull:
                    output = subprocess.check_output(command_with_args, cwd=cwd, env=env, stderr=devnull)
            else:
                output = subprocess.check_output(command_with_args, cwd=cwd, env=env)

            if verbose:
                sys.stdout.write(output.decode())

        except subprocess.CalledProcessError as e:
            sys.stderr.write(f"Command '{command}' failed with error: {e}")
